GrammarTopic(slug="conditional-b2",title="Conditional mood",level="B2",category="grammar",summary="Express hypotheses, wishes and polite proposals.",explanation="The Slovak conditional uses the particle by and past-tense participial forms.",examples=[GrammarExample(text="Pomohol by som ti."),GrammarExample(text="Keby som mal čas, cestoval by som.")]),
